read_table <- function(path) {
  lines <- strsplit(readLines(path),",",fixed=TRUE)
  names <- lines[[1L]][-1L]
  records <- lines[-1L]
  ids <- vapply(records,`[`,character(1),1L)
  values <- do.call(
      rbind,
      lapply(records,function(row) as.numeric(replace(row[-1L],row[-1L] == "NA",NA_character_)))
  )
  list(names=names,ids=ids,values=values)
}
load_dataset <- function() {
  settings <- list()
  for (line in readLines("input/params.txt")) {
    words <- strsplit(line," ",fixed=TRUE)[[1L]]
    key <- words[1L]
    settings[[key]] <- if (key %in% c("MISSING","SCALING","COMPONENTS")) words[2L] else as.numeric(words[-1L])
  }
  list(
      data=read_table("input/data.csv"),
      supplementary=read_table("input/supplementary.csv"),
      settings=settings
  )
}

off_diagonal <- function(matrix) {
  result <- 0
  for (p in seq_len(nrow(matrix)-1L)) for (q in seq.int(
      p+1L,
      nrow(matrix)
  )) result <- result+matrix[p,q]*matrix[p,q]
  result
}
jacobi <- function(matrix) {
  a <- matrix
  n <- nrow(matrix)
  v <- identity_matrix(n)
  initial <- off_diagonal(a)
  sweeps <- 0L
  if (initial > 0) for (number in seq_len(100L)) {
    for (p in seq_len(n-1L)) for (q in seq.int(p+1L,n)) {
      if (a[p,q] == 0) next
      theta <- (a[q,q]-a[p,p])/(2*a[p,q])
      t <- 1/(abs(theta)+sqrt(theta*theta+1))
      if (theta < 0) t <- -t
      c <- 1/sqrt(t*t+1)
      s <- t*c
      for (r in seq_len(n)) {
        if (r == p || r == q) next
        x <- a[r,p]
        y <- a[r,q]
        a[r,p] <- a[p,r] <- c*x-s*y
        a[r,q] <- a[q,r] <- s*x+c*y
      }
      value <- a[p,q]
      a[p,p] <- a[p,p]-t*value
      a[q,q] <- a[q,q]+t*value
      a[p,q] <- a[q,p] <- 0
      for (r in seq_len(n)) {
        x <- v[r,p]
        y <- v[r,q]
        v[r,p] <- c*x-s*y
        v[r,q] <- s*x+c*y
      }
    }
    remaining <- off_diagonal(a)
    if (sweeps == 0L && remaining < 1e-16*initial) sweeps <- number
    if (remaining < 1e-22*initial) break
  }
  order <- order(-diag(a),seq_len(n))
  list(values=diag(a)[order],vectors=lapply(order,function(k) orient(normalize(v[,k]))),sweeps=sweeps)
}
power_iteration <- function(matrix,references) {
  b <- matrix
  components <- list()
  for (reference in references) {
    x <- rep(1,length(reference))
    agreement <- NULL
    for (step in seq_len(1000L)) {
      x <- normalize(multiply(b,x))
      difference <- min(max_difference(x,reference),max_difference(x,-reference))
      if (is.null(agreement) && difference < 1e-6) agreement <- step
    }
    value <- dot_product(x,multiply(b,x))
    vector <- orient(normalize(x))
    b <- deflate(b,value,vector)
    components[[length(components)+1L]] <- list(value=value,vector=vector,agreement=agreement)
  }
  components
}

sequential_sum <- function(values) {
  result <- 0
  for (value in values) result <- result+value
  result
}
identity_matrix <- function(n) diag(n)
dot_product <- function(a,b) sequential_sum(a*b)
multiply <- function(matrix,vector) vapply(
    seq_len(nrow(matrix)),
    function(i) dot_product(matrix[i,],vector),
    numeric(1)
)
vector_length <- function(vector) sqrt(dot_product(vector,vector))
normalize <- function(vector) vector/vector_length(vector)
orient <- function(vector) if (vector[which.max(abs(vector))] < 0) -vector else vector
max_difference <- function(a,b) max(abs(a-b))
deflate <- function(matrix,value,vector) {
  for (i in seq_len(nrow(matrix))) for (j in seq_len(ncol(matrix))) matrix[i,j] <- matrix[
      i,
      j
  ]-value*vector[i]*vector[j]
  matrix
}
gauss_jordan <- function(matrix) {
  n <- nrow(matrix)
  augmented <- cbind(matrix,identity_matrix(n))
  determinant <- 1
  for (k in seq_len(n)) {
    pivot <- augmented[k,k]
    determinant <- determinant*pivot
    augmented[k,] <- augmented[k,]/pivot
    for (i in seq_len(n)) {
      if (i == k) next
      gamma <- augmented[i,k]
      for (h in seq_len(2L*n)) augmented[i,h] <- augmented[i,h]-gamma*augmented[k,h]
    }
  }
  list(inverse=augmented[,seq.int(n+1L,2L*n),drop=FALSE],determinant=determinant)
}

new_grid <- function(rows,columns) matrix(" ",rows,columns)
framed <- function(grid) {
  border <- paste0("+",strrep("-",ncol(grid)),"+")
  c(
      border,
      vapply(seq_len(nrow(grid)),function(i) paste0("|",paste(grid[i,],collapse=""),"|"),character(1)),
      border
  )
}
grid_index <- function(fraction,n) min(floor(fraction*n),n-1L)
rounded_position <- function(fraction,n) floor(fraction*n+0.5)
biplot_cell <- function(x,y,x_limit,y_limit,width,height) c(
    grid_index((y_limit-y)/(2*y_limit),height),
    grid_index((x+x_limit)/(2*x_limit),width)
)
circle_cell <- function(a,b,radius) c(
    radius %/% 2L+1L-rounded_position(b,radius/2),
    radius+1L+rounded_position(a,radius)
)
diagnostic_cell <- function(t2,spe,x,y,width,height) c(
    height-1L-grid_index(spe/y,height),
    grid_index(t2/x,width)
)
shaft_cells <- function(origin,tip) {
  dr <- tip[1L]-origin[1L]
  dc <- tip[2L]-origin[2L]
  steps <- max(abs(dc),abs(dr))
  if (steps <= 1L) return(list())
  lapply(seq_len(steps-1L),function(s) c(origin[1L]+sign(dr)*((2*s*abs(dr)+steps) %/% (2*steps)),
    origin[2L]+sign(dc)*((2*s*abs(dc)+steps) %/% (2*steps))))
}
shaft_character <- function(origin,tip) {
  dr <- tip[1L]-origin[1L]
  dc <- tip[2L]-origin[2L]
  if (2*abs(dr) <= abs(dc)) "-" else if (2*abs(dc) <= abs(dr)) "|" else if (dc*dr < 0) "/" else "\\"
}
scree_line <- function(n,kaiser,broken,width) paste0("|",paste(vapply(seq_len(width),function(p)
  if (p == broken) "o" else if (p == kaiser) ":" else if (p <= n) "#" else " ",character(1)),collapse=""),"|")
